 <section class="arena-wrap" id="arena"><div class="arena-top"><div class="arena-tag"><i class="dot"></i> FIRERIDGE BASIN</div><div class="round-tag">SECTOR <span id="sector">01</span> <span style="color:#405a55">/</span> ENDLESS</div></div><canvas class="arena-canvas" id="gameCanvas" aria-label="3D snake wildfire game board"></canvas><div class="arena-bottom"><div class="objective">SURVIVE THE SPREAD<strong id="goalText">Collect water · avoid fire</strong></div><div class="boost-label">✦ FLARE <span>SPACE</span></div></div><div class="touch-controls" aria-label="Direction controls"><button class="touch-btn up" data-dir="up" aria-label="Move up">▲</button><button class="touch-btn left" data-dir="left" aria-label="Move left">◀</button><button class="touch-btn down" data-dir="down" aria-label="Move down">▼</button><button class="touch-btn right" data-dir="right" aria-label="Move right">▶</button></div>
 <div class="overlay" id="overlay"><div class="modal"><div class="eyebrow" id="modalEyebrow">A WILDFIRE IS SPREADING</div><h1 id="modalTitle">EMBER <em>ZERO</em></h1><p id="modalText">Grow your rescue snake, collect water, and extinguish the flames before the basin burns.</p><button class="primary-btn" id="startBtn">START RESCUE RUN</button><div class="modal-foot">ARROWS / WASD TO MOVE &nbsp;·&nbsp; SPACE TO BURST</div></div></div></section>
 <aside class="rail"><section class="panel action-panel"><div class="action-title">RESCUE GEAR <span>Q</span></div><div class="power-row"><div class="power-icon">✺</div><div class="power-copy"><b>Water burst</b><small>Clear fire in a radius</small></div><div class="cooldown" id="burstReady">READY</div></div><div class="power-meter"><i id="burstMeter"></i></div></section><section class="panel controls-panel"><div class="controls-head">HOW TO SURVIVE</div><div class="controls-copy">Guide your crew around the basin. Snag water to grow, then blaze through nearby fire with a burst.</div><div class="desktop-keys"><span class="blank">·</span><span>↑</span><span class="blank">·</span><span>←</span><span>↓</span><span>→</span></div><div class="controls-copy" style="text-align:center;margin-top:0">W A S D or arrow keys<br><span class="keycap">SPACE</span> Water burst &nbsp; <span class="keycap">P</span> Pause</div></section><div class="bottom-hint">A LITTLE WATER GOES A LONG WAY</div></aside></main></div>
 <script>
+(()=>{
+const canvas=document.getElementById('gameCanvas'),ctx=canvas.getContext('2d');
+const $=id=>document.getElementById(id);const N=17;
+const dirs={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};
+let state='ready',snake=[],direction='right',nextDirection='right',water=null,fires=[],particles=[],score=0,waterCollected=0,fireConsumed=0,turn=0,heat=0,best=Number(localStorage.getItem('emberBest')||0),lastStep=0,acc=0,burstAt=0,frame=0,sw=0,sh=0,dpr=1,tileW=20,tileH=10,boardTop=0;
+$('bestScore').textContent=String(best).padStart(3,'0');
+function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);sw=Math.max(1,r.width);sh=Math.max(1,r.height);canvas.width=Math.round(sw*dpr);canvas.height=Math.round(sh*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);tileW=Math.min((sw-36)/N,(sh-(innerWidth<=850?160:72))/(N*.54));tileW=Math.max(8,tileW);tileH=tileW*.5;boardTop=(sh-N*tileH)/2+tileH*.38;}
+new ResizeObserver(resize).observe(canvas);window.addEventListener('resize',resize);resize();
+function pos(x,y){return{x:sw/2+(x-y)*tileW*.5,y:boardTop+(x+y)*tileH*.5};}
+function inside(x,y){return x>=0&&y>=0&&x<N&&y<N}
+function occupied(x,y){return snake.some(p=>p.x===x&&p.y===y)||fires.some(p=>p.x===x&&p.y===y)}
+function freeCell(){for(let i=0;i<500;i++){let p={x:1+Math.floor(Math.random()*(N-2)),y:1+Math.floor(Math.random()*(N-2))};if(!occupied(p.x,p.y)&&(!water||water.x!==p.x||water.y!==p.y))return p}return{x:2,y:2}}
+function freshGame(){snake=[{x:8,y:8},{x:7,y:8},{x:6,y:8}];direction=nextDirection='right';waterCollected=fireConsumed=score=turn=heat=0;fires=[];particles=[];for(let i=0;i<6;i++){let p=freeCell();if(Math.abs(p.x-8)+Math.abs(p.y-8)>4)fires.push(p)}water=freeCell();burstAt=0;acc=0;updateHud()}
+function updateHud(){ $('score').textContent=String(score).padStart(3,'0');$('waterCount').textContent=String(waterCollected).padStart(2,'0');$('fireCount').textContent=String(fireConsumed).padStart(2,'0');let pct=Math.min(100,Math.round((fires.length/(N*N))*340+heat*2));$('heatFill').style.width=pct+'%';$('heatLabel').textContent=pct<35?'LOW':pct<68?'RISING':'CRITICAL';$('missionProgress').style.width=Math.min(100,waterCollected*10)+'%';$('sector').textContent=String(1+Math.floor(score/120)).padStart(2,'0');$('statusText').textContent=state==='playing'?'LIVE IN FIELD':state==='paused'?'PAUSED':state==='over'?'RUN ENDED':'READY TO RUN';$('burstReady').textContent=frame-burstAt>=240?'READY':Math.ceil((240-(frame-burstAt))/60)+'s';$('burstMeter').style.width=Math.min(100,Math.max(0,100-(frame-burstAt)/2.4))+'%';$('goalText').textContent=fires.length>10?'Fire closing in · make a path':'Collect water · avoid fire';}
+function openOverlay(kind){const o=$('overlay');o.classList.remove('hidden');if(kind==='ready'){$('modalEyebrow').textContent='A WILDFIRE IS SPREADING';$('modalTitle').innerHTML='EMBER <em>ZERO</em>';$('modalText').textContent='Grow your rescue snake, collect water, and extinguish the flames before the basin burns.';$('startBtn').textContent='START RESCUE RUN'}else if(kind==='paused'){$('modalEyebrow').textContent='TAKE A BREATHER';$('modalTitle').innerHTML='RUN <em>PAUSED</em>';$('modalText').textContent='The fire waits for no one. Pick up where you left off when you’re ready.';$('startBtn').textContent='RESUME RUN'}else{$('modalEyebrow').textContent='THE BASIN WENT DARK';$('modalTitle').innerHTML='RUN <em>OVER</em>';$('modalText').textContent=`You survived ${score} points, saved ${fireConsumed} fire cells, and collected ${waterCollected} water drops.`;$('startBtn').textContent='RUN IT BACK'}}
+function start(){if(state==='paused'){state='playing';$('overlay').classList.add('hidden');return}freshGame();state='playing';lastStep=performance.now();$('overlay').classList.add('hidden');updateHud()}
+function pause(){if(state==='playing'){state='paused';openOverlay('paused')}else if(state==='paused')start()}
+function gameOver(){state='over';if(score>best){best=score;localStorage.setItem('emberBest',best);$('bestScore').textContent=String(best).padStart(3,'0')}openOverlay('over');updateHud()}
+function setDirection(d){if(state!=='playing')return;let a=dirs[d],b=dirs[direction];if(a[0]===-b[0]&&a[1]===-b[1])return;nextDirection=d}
+function burst(){if(state!=='playing'||frame-burstAt<240)return;burstAt=frame;let head=snake[0],before=fires.length;fires=fires.filter(f=>Math.abs(f.x-head.x)+Math.abs(f.y-head.y)>3);let gone=before-fires.length;fireConsumed+=gone;score+=gone*8;for(let i=0;i<20;i++){let a=Math.random()*Math.PI*2,r=Math.random()*tileW*2,p=pos(head.x,head.y);particles.push({x:p.x+Math.cos(a)*r,y:p.y+Math.sin(a)*r,vx:Math.cos(a)*(1+Math.random()*2),vy:Math.sin(a)*(1+Math.random()*2),life:30,color:i%2?'#9bffd0':'#b7fff0'})}updateHud()}
+function step(){if(state!=='playing')return;direction=nextDirection;const [dx,dy]=dirs[direction],head={x:snake[0].x+dx,y:snake[0].y+dy};if(!inside(head.x,head.y)||fires.some(f=>f.x===head.x&&f.y===head.y)||snake.slice(0,-1).some(p=>p.x===head.x&&p.y===head.y)){gameOver();return}snake.unshift(head);let ate=water&&head.x===water.x&&head.y===water.y;if(ate){waterCollected++;score+=20;water=freeCell();for(let i=0;i<10;i++){let p=pos(head.x,head.y);particles.push({x:p.x,y:p.y,vx:(Math.random()-.5)*3,vy:-Math.random()*3,life:24,color:'#83f8ff'})}}else snake.pop();score+=1;turn++;if(turn%5===0){heat=Math.min(100,heat+3);spreadFire()}if(turn%9===0&&!water)water=freeCell();if(fires.length===0){fireConsumed+=1;score+=10;fires.push(freeCell())}if(score>best){best=score;$('bestScore').textContent=String(best).padStart(3,'0')}updateHud()}
+function spreadFire(){if(fires.length>=32)return;let sources=fires.slice();for(const f of sources){if(Math.random()>.3)continue;const options=[[1,0],[-1,0],[0,1],[0,-1]].map(([x,y])=>({x:f.x+x,y:f.y+y})).filter(p=>inside(p.x,p.y)&&!occupied(p.x,p.y)&&(!water||water.x!==p.x||water.y!==p.y));if(options.length){fires.push(options[Math.floor(Math.random()*options.length)]);break}}}
+window.addEventListener('keydown',e=>{let map={ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'};if(map[e.key]){e.preventDefault();setDirection(map[e.key])}if(e.code==='Space'){e.preventDefault();burst()}if(e.key==='p'||e.key==='P'||e.key==='Escape')pause();if(e.key==='Enter'&&(state==='ready'||state==='over'))start()});
+$('startBtn').addEventListener('click',start);$('pauseBtn').addEventListener('click',pause);document.querySelectorAll('.touch-btn').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();setDirection(b.dataset.dir)})});let swipe=null;canvas.addEventListener('pointerdown',e=>{swipe={x:e.clientX,y:e.clientY}});canvas.addEventListener('pointerup',e=>{if(!swipe)return;let dx=e.clientX-swipe.x,dy=e.clientY-swipe.y;if(Math.max(Math.abs(dx),Math.abs(dy))>24)setDirection(Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up'));swipe=null});

