$('startBtn').addEventListener('click',start);$('pauseBtn').addEventListener('click',pause);document.querySelectorAll('.touch-btn').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();setDirection(b.dataset.dir)})});let swipe=null;canvas.addEventListener('pointerdown',e=>{swipe={x:e.clientX,y:e.clientY}});canvas.addEventListener('pointerup',e=>{if(!swipe)return;let dx=e.clientX-swipe.x,dy=e.clientY-swipe.y;if(Math.max(Math.abs(dx),Math.abs(dy))>24)setDirection(Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up'));swipe=null});
function diamond(x,y,w,h,fill,stroke){ctx.beginPath();ctx.moveTo(x,y-h);ctx.lineTo(x+w,y);ctx.lineTo(x,y+h);ctx.lineTo(x-w,y);ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.6;ctx.stroke()}}
function drawBoard(){let cx=sw/2,outerW=N*tileW*.5,outerH=N*tileH*.5;const glow=ctx.createRadialGradient(cx,boardTop+outerH,4,cx,boardTop+outerH,outerW*1.35);glow.addColorStop(0,'#1c3e34');glow.addColorStop(1,'#0b1719');ctx.fillStyle=glow;ctx.fillRect(0,0,sw,sh);
// soft board shadow
ctx.save();ctx.globalAlpha=.35;for(let i=0;i<N;i++){let p=pos(i,N-1);diamond(p.x+5,p.y+8,tileW*.51,tileH*.52,'#020707')}ctx.restore();
for(let sum=0;sum<2*N-1;sum++){for(let x=Math.max(0,sum-N+1);x<=Math.min(N-1,sum);x++){let y=sum-x,p=pos(x,y),alt=(x+y)%2;let color=alt?'#18332e':'#142d29';diamond(p.x,p.y,tileW*.495,tileH*.49,color,'#24453c');diamond(p.x,p.y+tileH*.035,tileW*.43,tileH*.40,alt?'#1a3731':'#17332d')
// subtle scorched patches
if((x*13+y*7)%29===2){ctx.globalAlpha=.13;diamond(p.x,p.y,tileW*.31,tileH*.2,'#b7603b');ctx.globalAlpha=1}
}}
// glowing perimeter
ctx.save();ctx.shadowColor='#69ffb4';ctx.shadowBlur=15;ctx.strokeStyle='#7affe044';ctx.lineWidth=1.1;ctx.beginPath();let a=pos(0,0),b=pos(N-1,0),c=pos(N-1,N-1),d=pos(0,N-1);ctx.moveTo(a.x,a.y-tileH*.5);ctx.lineTo(b.x+tileW*.5,b.y);ctx.lineTo(c.x,c.y+tileH*.5);ctx.lineTo(d.x-tileW*.5,d.y);ctx.closePath();ctx.stroke();ctx.restore();
}
function drawFlame(f){let p=pos(f.x,f.y),phase=frame*.11+f.x*1.7+f.y,scale=.82+Math.sin(phase)*.1,w=tileW*.29*scale,h=tileH*1.8*scale;ctx.save();ctx.translate(p.x,p.y-tileH*.42);ctx.globalCompositeOperation='lighter';let glow=ctx.createRadialGradient(0,-h*.35,0,0,-h*.25,h*1.2);glow.addColorStop(0,'#ffb14b55');glow.addColorStop(1,'#ff512100');ctx.fillStyle=glow;ctx.beginPath();ctx.ellipse(0,-h*.2,w*1.9,h*.9,0,0,Math.PI*2);ctx.fill();ctx.shadowColor='#ff6b36';ctx.shadowBlur=tileW*.4;
ctx.beginPath();ctx.moveTo(-w*.8,0);ctx.quadraticCurveTo(-w*1.2,-h*.55,-w*.16,-h);ctx.quadraticCurveTo(-w*.18,-h*.47,w*.25,-h*.72);ctx.quadraticCurveTo(w*.16,-h*.18,w*.78,-h*.57);ctx.quadraticCurveTo(w*1.1,-h*.15,w*.58,0);ctx.closePath();let grad=ctx.createLinearGradient(0,-h,0,0);grad.addColorStop(0,'#ffcf70');grad.addColorStop(.38,'#ff7840');grad.addColorStop(1,'#e84a2e');ctx.fillStyle=grad;ctx.fill();ctx.shadowBlur=0;ctx.beginPath();ctx.moveTo(-w*.35,0);ctx.quadraticCurveTo(-w*.42,-h*.43,w*.03,-h*.67);ctx.quadraticCurveTo(w*.1,-h*.29,w*.42,-h*.45);ctx.quadraticCurveTo(w*.52,-h*.12,w*.2,0);ctx.closePath();ctx.fillStyle='#ffe29a';ctx.fill();ctx.restore()}

